#include "stdafx.h"#include "H_Class.h"static SBlockCreate MINPULSE( "MINPULSE", SH_MINPULSE::Create );#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_MINPULSE,W_MINPULSE,10)void SH_MINPULSE::InitParm(){#include "Blocks/MINPULSE.h"   s_defFlag = SVarInfo::efParam;#include "Blocks/MINPULSE_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}class MINPULSE_IMPL : public W_MINPULSE{public:  void StepT( SStepCalcParams &dt, BYTE prevIn );};void SH_MINPULSE::StepT( SStepCalcParams &dt ){  BYTE prevIn = W->IN;  InputConnectionsTransfer();  MINPULSE_IMPL *impl = reinterpret_cast<MINPULSE_IMPL*>(W);  impl->StepT( dt, prevIn );  OutputConnectionsTransfer();}//////////////////////////////////////////////////////////////////////////void MINPULSE_IMPL::StepT( SStepCalcParams &dt, BYTE prevIn ){  if( !prevIn && IN )  {    OUT = true;    TIMER += dt;    return;  }  if( TIMER > 0 )  {    TIMER += dt;    if( TIMER >= PULSEWIDTH )    {      if( !IN )      {        OUT = false;        TIMER = 0;        return;      }    }  }}